package repoctl

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
)

type ReadmeOptions struct {
	Root string
}

func UpdateReadme(opts ReadmeOptions) error {
	if opts.Root == "" {
		return fmt.Errorf("repo root is required")
	}
	benchPath := filepath.Join(opts.Root, "benchmarks.json")
	raw, err := os.ReadFile(benchPath)
	if err != nil {
		if os.IsNotExist(err) {
			fmt.Fprintln(os.Stderr, "update-readme: benchmarks.json not found; skipping")
			return nil
		}
		return err
	}
	var data struct {
		Binary struct {
			SizeMB       json.RawMessage `json:"size_mb"`
			LastMeasured string          `json:"last_measured"`
		} `json:"binary"`
		Code struct {
			TestCount    json.RawMessage `json:"test_count"`
			GoFiles      json.RawMessage `json:"go_files"`
			GoLines      json.RawMessage `json:"go_lines"`
			Dependencies json.RawMessage `json:"dependencies"`
		} `json:"code"`
	}
	if err := json.Unmarshal(raw, &data); err != nil {
		return err
	}

	readmePath := filepath.Join(opts.Root, "README.md")
	readme, err := os.ReadFile(readmePath)
	if err != nil {
		return err
	}
	content := string(readme)

	if sizeMB, err := benchmarkSizeMB(data.Binary.SizeMB); err == nil && sizeMB != "" {
		content = updateBinarySizeSummaries(content, sizeMB)
	}

	if testCount, err := intVal(data.Code.TestCount); err == nil && testCount > 0 {
		re := regexp.MustCompile(`[0-9,]+\+ tests`)
		content = re.ReplaceAllString(content, fmt.Sprintf("%d+ tests", testCount))
	}

	if goFiles, err := intVal(data.Code.GoFiles); err == nil && goFiles > 0 {
		re := regexp.MustCompile(`[0-9,]+\+ Go source files`)
		content = re.ReplaceAllString(content, fmt.Sprintf("%d+ Go source files", goFiles))
	}

	if goLines, err := intVal(data.Code.GoLines); err == nil && goLines > 0 {
		re := regexp.MustCompile(`[0-9,]+ lines of Go`)
		content = re.ReplaceAllString(content, fmt.Sprintf("%d lines of Go", goLines))
	}

	if deps, err := intVal(data.Code.Dependencies); err == nil && deps > 0 {
		re := regexp.MustCompile(`[0-9,]+ dependencies`)
		content = re.ReplaceAllString(content, fmt.Sprintf("%d dependencies", deps))
	}

	release := readReleaseMetadata(opts.Root)
	if release.Tag != "" {
		content = updateReleaseMetadata(content, release, data.Binary.SizeMB, data.Binary.LastMeasured)
	}
	return os.WriteFile(readmePath, []byte(content), 0o644)
}

func updateBinarySizeSummaries(content, sizeMB string) string {
	replacements := []struct {
		re   *regexp.Regexp
		repl string
	}{
		{regexp.MustCompile(`(Binary size: )~[0-9.]+ MB`), "${1}~" + sizeMB + " MB"},
		{regexp.MustCompile(`(Linux build )~[0-9.]+ MB`), "${1}~" + sizeMB + " MB"},
		{regexp.MustCompile(`(current Linux build measures )~[0-9.]+ MB`), "${1}~" + sizeMB + " MB"},
		{regexp.MustCompile(`(Linux build at )~[0-9.]+ MB`), "${1}~" + sizeMB + " MB"},
	}
	for _, replacement := range replacements {
		content = replacement.re.ReplaceAllString(content, replacement.repl)
	}
	return content
}

type releaseMetadata struct {
	Tag string
	URL string
}

func readReleaseMetadata(root string) releaseMetadata {
	raw, err := os.ReadFile(filepath.Join(root, "webpages", "landing", "src", "data", "release.json"))
	if err == nil {
		var data struct {
			Version string `json:"version"`
			Tag     string `json:"tag"`
			URL     string `json:"url"`
		}
		if json.Unmarshal(raw, &data) == nil {
			tag := data.Tag
			if tag == "" && data.Version != "" {
				tag = "v" + data.Version
			}
			if tag != "" {
				url := data.URL
				if url == "" {
					url = "https://github.com/TrebuchetDynamics/gormes-agent/releases/tag/" + tag
				}
				return releaseMetadata{Tag: tag, URL: url}
			}
		}
	}

	raw, err = os.ReadFile(filepath.Join(root, "cmd", "gormes", "version.go"))
	if err != nil {
		return releaseMetadata{}
	}
	match := regexp.MustCompile(`var\s+Version\s*=\s*"([^"]+)"`).FindStringSubmatch(string(raw))
	if len(match) != 2 {
		return releaseMetadata{}
	}
	tag := "v" + match[1]
	return releaseMetadata{
		Tag: tag,
		URL: "https://github.com/TrebuchetDynamics/gormes-agent/releases/tag/" + tag,
	}
}

func updateReleaseMetadata(content string, release releaseMetadata, sizeRaw json.RawMessage, measured string) string {
	latest := regexp.MustCompile(`Latest public release: \[[^\]]+\]\([^)]+\)\.`)
	content = latest.ReplaceAllString(content, fmt.Sprintf("Latest public release: [%s](%s).", release.Tag, release.URL))

	devHead := regexp.MustCompile("Current `development` head after `[^`]+`")
	content = devHead.ReplaceAllString(content, fmt.Sprintf("Current `development` head after `%s`", release.Tag))

	size, err := benchmarkSizeMB(sizeRaw)
	if err != nil || size == "" || measured == "" {
		return content
	}

	summary := fmt.Sprintf("Release %s publishes static Go binaries for Linux, macOS, Windows, and Termux/Android across the supported release matrix. The current benchmark mirror reports a Linux build at ~%s MB (`benchmarks.json`, %s).",
		release.Tag, size, measured)
	releaseSummary := regexp.MustCompile("Release v[0-9][^\\n]+?\\. The current benchmark mirror reports a Linux build at ~[0-9.]+ MB \\(`benchmarks\\.json`, [0-9-]+\\)\\.")
	return releaseSummary.ReplaceAllString(content, summary)
}

func benchmarkSizeMB(raw json.RawMessage) (string, error) {
	if len(raw) == 0 {
		return "", nil
	}
	var value string
	if err := json.Unmarshal(raw, &value); err == nil {
		return value, nil
	}
	var number float64
	if err := json.Unmarshal(raw, &number); err == nil {
		return strconv.FormatFloat(number, 'f', -1, 64), nil
	}
	return "", fmt.Errorf("benchmarks.json binary.size_mb has unsupported type")
}

func intVal(raw json.RawMessage) (int, error) {
	if len(raw) == 0 {
		return 0, nil
	}
	var n float64
	if err := json.Unmarshal(raw, &n); err != nil {
		return 0, err
	}
	return int(n), nil
}

package repoctl

import (
	"embed"
	"encoding/json"
	"fmt"
	"io/fs"
	"path"
	"path/filepath"
	"sort"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/planning/progress"
)

//go:embed rowpacks/*.json
var rowPackFS embed.FS

type ProgressSeedOptions struct {
	Root         string
	ProgressPath string
	Set          string
}

type ProgressSeedResult struct {
	Set          string
	Added        int
	Skipped      int
	AddedNames   []string
	SkippedNames []string
	TotalItems   int
}

type progressRowPack struct {
	Name string            `json:"name"`
	Rows []progressRowSeed `json:"rows"`
}

type progressRowSeed struct {
	Phase    string        `json:"phase"`
	Subphase string        `json:"subphase"`
	Item     progress.Item `json:"item"`
}

func SeedProgressRows(opts ProgressSeedOptions) (ProgressSeedResult, error) {
	if opts.Root == "" {
		opts.Root = "."
	}
	opts.Set = strings.TrimSpace(opts.Set)
	if opts.Set == "" {
		opts.Set = "fleet"
	}
	pack, err := loadProgressRowPack(opts.Set)
	if err != nil {
		return ProgressSeedResult{}, err
	}
	path := opts.ProgressPath
	if path == "" {
		path = filepath.Join(opts.Root, "webpages", "docs", "content", "building-gormes", "architecture_plan", "progress.json")
	}
	doc, err := progress.Load(path)
	if err != nil {
		return ProgressSeedResult{}, err
	}

	result := ProgressSeedResult{Set: pack.Name}
	for _, row := range pack.Rows {
		phase, ok := doc.Phases[row.Phase]
		if !ok {
			return result, fmt.Errorf("progress seed %s: phase %s not found", pack.Name, row.Phase)
		}
		subphase, ok := phase.Subphases[row.Subphase]
		if !ok {
			return result, fmt.Errorf("progress seed %s: subphase %s not found in phase %s", pack.Name, row.Subphase, row.Phase)
		}
		if progressSubphaseHasItem(subphase, row.Item.Name) {
			result.Skipped++
			result.SkippedNames = append(result.SkippedNames, row.Item.Name)
			continue
		}
		if len(subphase.Items) == 0 {
			subphase.Status = ""
		}
		subphase.Items = append(subphase.Items, row.Item)
		phase.Subphases[row.Subphase] = subphase
		doc.Phases[row.Phase] = phase
		result.Added++
		result.AddedNames = append(result.AddedNames, row.Item.Name)
	}

	if result.Added > 0 {
		if err := progress.Validate(doc); err != nil {
			return result, err
		}
		if err := progress.SaveProgress(path, doc); err != nil {
			return result, err
		}
	}
	result.TotalItems = doc.Stats().Items.Total
	return result, nil
}

func loadProgressRowPack(set string) (progressRowPack, error) {
	name := strings.TrimSpace(set)
	raw, err := rowPackFS.ReadFile(path.Join("rowpacks", name+".json"))
	if err != nil {
		if _, ok := err.(*fs.PathError); ok {
			return progressRowPack{}, fmt.Errorf("unknown progress row seed set %q (available: %s)", set, strings.Join(progressRowPackNames(), ", "))
		}
		return progressRowPack{}, err
	}
	var pack progressRowPack
	if err := json.Unmarshal(raw, &pack); err != nil {
		return progressRowPack{}, fmt.Errorf("parse progress row pack %s: %w", name, err)
	}
	if pack.Name == "" {
		pack.Name = name
	}
	return pack, nil
}

func progressRowPackNames() []string {
	matches, err := fs.Glob(rowPackFS, "rowpacks/*.json")
	if err != nil {
		return nil
	}
	names := make([]string, 0, len(matches))
	for _, match := range matches {
		base := path.Base(match)
		names = append(names, strings.TrimSuffix(base, path.Ext(base)))
	}
	sort.Strings(names)
	return names
}

func progressSubphaseHasItem(subphase progress.Subphase, name string) bool {
	for _, item := range subphase.Items {
		if item.Name == name {
			return true
		}
	}
	return false
}

package repoctl

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
)

const (
	sourcePairsManifestRel = "webpages/docs/content/building-gormes/architecture_plan/hermes-source-pairs.json"
	sourcePairsReportRel   = "webpages/docs/content/building-gormes/architecture_plan/hermes-source-pairs.md"
)

var highPriorityHermesSources = []string{
	"hermes_cli/default_soul.py",
	"hermes_cli/config.py",
	"hermes_cli/profiles.py",
	"agent/prompt_builder.py",
	"hermes_cli/main.py",
	"hermes_cli/commands.py",
	"hermes_cli/auth_commands.py",
	"gateway/run.py",
	"tools/skills_tool.py",
	"tools/skill_manager_tool.py",
	"tools/skills_sync.py",
	"run_agent.py",
	"cli.py",
}

type SourcePairOptions struct {
	Root                string
	ManifestPath        string
	ReportPath          string
	HermesSrc           string
	CurrentHermesSHA    string
	RequireHighPriority bool
}

type SourcePairsManifest struct {
	SchemaVersion string       `json:"schema_version"`
	HermesSHA     string       `json:"hermes_sha"`
	Pairs         []SourcePair `json:"pairs"`
}

type SourcePair struct {
	HermesFile           string   `json:"hermes_file"`
	GormesTargets        []string `json:"gormes_targets,omitempty"`
	Status               string   `json:"status"`
	Contract             string   `json:"contract"`
	Tests                []string `json:"tests,omitempty"`
	ProgressRows         []string `json:"progress_rows,omitempty"`
	UpstreamTests        []string `json:"upstream_tests,omitempty"`
	LastCheckedHermesSHA string   `json:"last_checked_hermes_sha"`
	Notes                string   `json:"notes,omitempty"`
}

type SourcePairsValidation struct {
	Manifest         SourcePairsManifest
	CurrentHermesSHA string
	Counts           map[string]int
	UnmappedHigh     []string
}

type SourcePairsSyncResult struct {
	Manifest           SourcePairsManifest
	CurrentHermesSHA   string
	ChangedHermesFiles []string
	DemotedCovered     []string
}

func ValidateSourcePairs(opts SourcePairOptions) (SourcePairsValidation, error) {
	manifest, err := loadSourcePairsManifest(opts)
	if err != nil {
		return SourcePairsValidation{}, err
	}
	root := sourcePairRoot(opts)
	hermesSrc := sourcePairHermesSrc(root, opts)
	currentSHA := opts.CurrentHermesSHA
	if currentSHA == "" && sourcePairIsGitCheckout(hermesSrc) {
		currentSHA, _ = sourcePairGitSHA(hermesSrc)
	}

	var errs []error
	if manifest.SchemaVersion == "" {
		errs = append(errs, errors.New("source-pairs: schema_version is required"))
	}
	if manifest.HermesSHA == "" {
		errs = append(errs, errors.New("source-pairs: hermes_sha is required"))
	}
	if currentSHA != "" && manifest.HermesSHA != "" && !shaMatches(currentSHA, manifest.HermesSHA) {
		errs = append(errs, fmt.Errorf("source-pairs: stale Hermes SHA manifest=%s current=%s", manifest.HermesSHA, currentSHA))
	}
	if len(manifest.Pairs) == 0 {
		errs = append(errs, errors.New("source-pairs: pairs must not be empty"))
	}

	seen := map[string]bool{}
	counts := map[string]int{}
	for i, pair := range manifest.Pairs {
		prefix := fmt.Sprintf("source-pairs: pair[%d] %s:", i, pair.HermesFile)
		if pair.HermesFile == "" {
			errs = append(errs, fmt.Errorf("%s hermes_file is required", prefix))
			continue
		}
		if seen[pair.HermesFile] {
			errs = append(errs, fmt.Errorf("%s duplicate hermes_file", prefix))
		}
		seen[pair.HermesFile] = true
		counts[pair.Status]++

		if !validSourcePairStatus(pair.Status) {
			errs = append(errs, fmt.Errorf("%s invalid status %q", prefix, pair.Status))
		}
		if strings.TrimSpace(pair.Contract) == "" {
			errs = append(errs, fmt.Errorf("%s contract is required", prefix))
		}
		if strings.TrimSpace(pair.LastCheckedHermesSHA) == "" {
			errs = append(errs, fmt.Errorf("%s last_checked_hermes_sha is required", prefix))
		}
		if currentSHA != "" && pair.LastCheckedHermesSHA != "" && !shaMatches(currentSHA, pair.LastCheckedHermesSHA) {
			errs = append(errs, fmt.Errorf("%s stale Hermes SHA row=%s current=%s", prefix, pair.LastCheckedHermesSHA, currentSHA))
		}
		if !sourcePairPathExists(filepath.Join(hermesSrc, filepath.FromSlash(pair.HermesFile))) {
			errs = append(errs, fmt.Errorf("%s missing Hermes file", prefix))
		}
		for _, test := range pair.UpstreamTests {
			if !sourcePairPathExists(filepath.Join(hermesSrc, filepath.FromSlash(test))) {
				errs = append(errs, fmt.Errorf("%s missing upstream test %q", prefix, test))
			}
		}
		for _, target := range pair.GormesTargets {
			if !sourcePairPathExists(filepath.Join(root, filepath.FromSlash(target))) {
				errs = append(errs, fmt.Errorf("%s missing Gormes target %q", prefix, target))
			}
		}
		if pair.Status == "covered" {
			if len(pair.GormesTargets) == 0 {
				errs = append(errs, fmt.Errorf("%s covered row requires gormes_targets", prefix))
			}
			if len(pair.Tests) == 0 {
				errs = append(errs, fmt.Errorf("%s covered row requires tests", prefix))
			}
		}
	}

	var unmappedHigh []string
	if opts.RequireHighPriority {
		for _, source := range highPriorityHermesSources {
			if !sourcePairPathExists(filepath.Join(hermesSrc, filepath.FromSlash(source))) {
				continue
			}
			if !seen[source] {
				unmappedHigh = append(unmappedHigh, source)
				errs = append(errs, fmt.Errorf("source-pairs: high-priority Hermes file is unmapped: %s", source))
			}
		}
	}

	sortSourcePairs(manifest.Pairs)
	validation := SourcePairsValidation{
		Manifest:         manifest,
		CurrentHermesSHA: currentSHA,
		Counts:           counts,
		UnmappedHigh:     unmappedHigh,
	}
	return validation, errors.Join(errs...)
}

func RenderSourcePairsReport(opts SourcePairOptions) (string, error) {
	validation, err := ValidateSourcePairs(opts)
	if err != nil {
		return "", err
	}
	manifest := validation.Manifest
	var b strings.Builder
	b.WriteString("# Hermes Source Pairs\n\n")
